 for(const auto&x:budgets)if(x.second.seen!=x.second.expected)throw std::runtime_error("dense engineering component denominator differs");auto close=[](double x,double y){return std::abs(x-y)<=1e-9*std::max({1.,std::abs(x),std::abs(y)});};if(used!=j.at("active_rows")||added!=j.at("new_active_rows")||!close(double(inherited),j.at("retained_parent_budget"))||!close(double(suffix),j.at("new_dense_budget"))||!close(double(inherited+suffix),j.at("actual_total_engineering_budget"))||j.at("source_noise_W_or_sigma_issued")!=false||j.at("statistical_precision_or_noise_independence_claimed")!=false)throw std::runtime_error("dense engineering/noise budget accounting differs");
 result.enabled=true;result.per_row_weight=std::move(w);result.receipt={{"schema","rinkfit.actual_dense6_engineering_source_weight_consumption.v1"},{"binding",cfg.at("engineering_dense_source_weights_v1")},{"parent_rows",old},{"active_rows",used},{"new_raw_rows",n-old},{"new_active_rows",added},{"new_unknown_rows_retained",n-old-added},{"unknown_source_weight_and_information_class_zero",true},{"retained_parent_budget",double(inherited)},{"new_dense_budget",double(suffix)},{"actual_total_engineering_budget",double(inherited+suffix)},{"original_parent_budget_bits_preserved",true},{"engineering_is_noise_likelihood",false},{"original_E_UV_Query_and_W_changed",false}};return result;
